/**
 * rv-abb-rapid.ts — ABB RAPID postprocessor (plan-773 Phase 5, F17; E2 put ABB
 * first). Port of `ABBRapidPostProcessor.cs`, formatting-faithful: every emitted
 * line is character-identical to the C# one for the same program.
 *
 * Its C# header, which is the contract this file keeps:
 *
 * > Produces a .mod module (MODULE/PROC main/ENDPROC/ENDMODULE) as a copy-paste
 * > text template. Default mode (AxisBased) uses MoveAbsJ + jointtarget and is
 * > robconf-free — the exact solved axis angles are emitted 1:1. The optional
 * > Cartesian mode (MoveJ/MoveL + robtarget) produces human-readable poses but
 * > requires the correct quaternion order [w,x,y,z] and a robconf derived from
 * > the axis angles. tooldata/wobjdata are not derived from the IK and fall back
 * > to tool0/wobj0 (maintain them on the controller).
 *
 * ## The two details that are easy to get wrong, and are asserted
 *
 * - **Quaternion order.** RAPID's `orient` is `[q1,q2,q3,q4] = [w,x,y,z]`
 *   (Hamilton). `RobotMoveInstruction.RotationQuat` is `[x,y,z,w]` (the house
 *   tuple). Emitting the tuple in its own order would produce a program that
 *   parses, runs and points the tool somewhere else.
 * - **`MoveAbsJ` takes no `\WObj`.** A joint move is work-object independent;
 *   adding the argument is a RAPID error, not a harmless extra.
 *
 * ## This file is a lazy chunk
 *
 * It is reached only through `rv-robot-vendors.ts`'s `import()`, so it is in a
 * chunk of its own and the default load carries none of it (plan-773 §2.5,
 * guarded by `tests/robot-export-lazy.node.test.ts`).
 */

import { RobotPostProcessor, type RobotExportFile } from '../rv-robot-postprocessor';
import type { RobotMoveInstruction, RobotProgram } from '../rv-robot-program';

/** Predefined RAPID `speeddata` values (`v5` … `v7000`). */
const PREDEF_V = [
  5, 10, 20, 30, 40, 50, 60, 80, 100, 150, 200, 300, 400, 500, 600, 800,
  1000, 1500, 2000, 2500, 3000, 4000, 5000, 6000, 7000,
] as const;

/** Predefined RAPID `zonedata` radii in mm (`z0` … `z200`). */
const ZONE_MM = [0, 1, 5, 10, 15, 20, 30, 40, 50, 60, 80, 100, 150, 200] as const;

/** Options of {@link ABBRapidPostProcessor}. */
export interface AbbRapidOptions {
  /** true => snap LinSpeed to the nearest predefined `v####` value. */
  snapToPredefined?: boolean;
}

/** ABB RAPID (`.mod`). See the module header. */
export class ABBRapidPostProcessor extends RobotPostProcessor {
  readonly displayName = 'ABB RAPID';
  readonly fileExtension = '.mod';

  /** true => snap LinSpeed to the nearest predefined `v####` value. */
  snapToPredefined = true;

  private consts: string[] = [];
  private body: string[] = [];
  private ptIndex = 0;
  private tool = 'tool0';
  private wobj = 'wobj0';

  constructor(options: AbbRapidOptions = {}) {
    super();
    if (options.snapToPredefined !== undefined) this.snapToPredefined = options.snapToPredefined;
  }

  getFileName(prog: RobotProgram): string {
    return sanitizeIdent(prog ? prog.Name : 'rvExportedPath');
  }

  override generate(prog: RobotProgram): string {
    this.program = prog;
    this.consts = [];
    this.body = [];
    this.ptIndex = 0;

    this.setTool(prog);
    this.setFrame(prog);

    for (const m of prog.Instructions) {
      if (m.MoveType === 'LIN') this.moveL(m);
      else this.moveJ(m); // PTP + PTPUnsynced
      this.emitSideEffects(m);
    }

    const moduleName = sanitizeIdent(prog.Name);
    const out: string[] = [];
    out.push(`MODULE ${moduleName}`);
    out.push('    ! Generated by realvirtual Robot Program Export (ABB RAPID) - Beta');
    out.push('    ! COPY-PASTE TEMPLATE - not a complete robot program.');
    out.push(`    ! Mode: ${this.axisBased ? 'MoveAbsJ (axis-based) -- robconf-free' : 'Cartesian (MoveJ/MoveL)'}`);
    out.push('    ! tooldata/wobjdata are NOT derived from IK -> tool0/wobj0 fallback (calibrate on controller).');
    const [ox, oy, oz] = prog.ToolOffsetMm;
    if (ox !== 0 || oy !== 0 || oz !== 0) {
      out.push(`    ! ToolOffset (approx, mm): [${this.fmt(ox)}, ${this.fmt(oy)}, ${this.fmt(oz)}]`);
    }
    out.push(...this.consts);
    out.push('');
    out.push('    PROC main()');
    out.push(...this.body);
    out.push('    ENDPROC');
    out.push('ENDMODULE');
    return `${out.join('\n')}\n`;
  }

  protected override emitFiles(prog: RobotProgram): RobotExportFile[] {
    return [{ fileName: this.getFileName(prog) + this.fileExtension, content: this.generate(prog) }];
  }

  protected override setTool(prog: RobotProgram): void {
    this.tool = sanitizeIdent(prog ? prog.ToolName : 'tool0');
  }

  protected override setFrame(_prog: RobotProgram): void {
    this.wobj = 'wobj0';
  }

  protected override moveJ(m: RobotMoveInstruction): void {
    const speed = this.speedToken(m);
    const zone = zoneToken(m);
    this.commentLine(m);
    if (this.axisBased) {
      const jt = `jt_p${this.ptIndex}`;
      this.appendJointtarget(jt, m.JointAngles);
      // MoveAbsJ is work-object independent -> no \WObj.
      this.body.push(`        MoveAbsJ ${jt}, ${speed}, ${zone}, ${this.tool};`);
    } else {
      const p = `p_p${this.ptIndex}`;
      this.appendRobtarget(p, m.PositionMm, m.RotationQuat, m.JointAngles);
      this.body.push(`        MoveJ ${p}, ${speed}, ${zone}, ${this.tool} \\WObj:=${this.wobj};`);
    }
    this.ptIndex++;
  }

  protected override moveL(m: RobotMoveInstruction): void {
    const speed = this.speedToken(m);
    const zone = zoneToken(m);
    this.commentLine(m);
    const p = `p_p${this.ptIndex}`;
    this.appendRobtarget(p, m.PositionMm, m.RotationQuat, m.JointAngles);
    this.body.push(`        MoveL ${p}, ${speed}, ${zone}, ${this.tool} \\WObj:=${this.wobj};`);
    this.ptIndex++;
  }

  protected override setDigitalOutput(signal: string, value: boolean): void {
    this.body.push(`        SetDO ${sanitizeIdent(signal)}, ${value ? 1 : 0};`);
  }

  protected override waitDigitalInput(signal: string, value: boolean): void {
    this.body.push(`        WaitDI ${sanitizeIdent(signal)}, ${value ? 1 : 0};`);
  }

  protected override waitTime(seconds: number): void {
    this.body.push(`        WaitTime ${this.fmt(seconds)};`);
  }

  private commentLine(m: RobotMoveInstruction): void {
    if (m.Comment) this.body.push(`        ! ${m.Comment}`);
  }

  /** `jointtarget := [[J1..J6]deg, [extax 9E9..]]` (from solved axis angles). */
  private appendJointtarget(name: string, axisDeg: readonly number[]): void {
    const a = (i: number): string => this.fmt(axisDeg[i] ?? 0);
    this.consts.push(
      `    CONST jointtarget ${name} := [[${a(0)}, ${a(1)}, ${a(2)}, `
      + `${a(3)}, ${a(4)}, ${a(5)}], [9E9,9E9,9E9,9E9,9E9,9E9]];`,
    );
  }

  /**
   * `robtarget := [[x,y,z]mm, [q1..q4], [cf1,cf4,cf6,cfx], [extax 9E9..]]`.
   * Quaternion order is `[w,x,y,z]`: q1 = `.w`, q2 = `.x`, q3 = `.y`, q4 = `.z`.
   */
  private appendRobtarget(
    name: string,
    posMm: readonly [number, number, number],
    q: readonly [number, number, number, number],
    axisDeg: readonly number[],
  ): void {
    const cf1 = Math.floor((axisDeg[0] ?? 0) / 90);
    const cf4 = Math.floor((axisDeg[3] ?? 0) / 90);
    const cf6 = Math.floor((axisDeg[5] ?? 0) / 90);
    const cfx = (axisDeg[4] ?? 0) < 0 ? 1 : 0; // common heuristic (A5<0 -> 1); default 0
    this.consts.push(
      `    CONST robtarget ${name} := [[${this.fmt(posMm[0])}, ${this.fmt(posMm[1])}, ${this.fmt(posMm[2])}], `
      + `[${this.fmt(q[3])}, ${this.fmt(q[0])}, ${this.fmt(q[1])}, ${this.fmt(q[2])}], ` // [w,x,y,z] Hamilton
      + `[${cf1}, ${cf4}, ${cf6}, ${cfx}], [9E9,9E9,9E9,9E9,9E9,9E9]];`,
    );
  }

  private speedToken(m: RobotMoveInstruction): string {
    if (this.snapToPredefined) {
      let best: number = PREDEF_V[0];
      for (const v of PREDEF_V) if (v <= m.LinSpeedMmS) best = v;
      return `v${best}`;
    }
    const id = `v_seg${this.ptIndex}`;
    // speeddata = [tcp mm/s, reorient deg/s, extlin mm/s, extrot deg/s]
    this.consts.push(`    CONST speeddata ${id} := [${this.fmt(m.LinSpeedMmS)}, 500, 5000, 1000];`);
    return id;
  }
}

/** `fine` (exact stop) or the nearest predefined zone below the blend radius. */
function zoneToken(m: RobotMoveInstruction): string {
  if (!m.EnableBlending || m.BlendRadiusMm <= 0) return 'fine';
  let best: number = ZONE_MM[0];
  for (const z of ZONE_MM) if (z <= m.BlendRadiusMm) best = z;
  return `z${best}`;
}

/**
 * Strips characters illegal in a RAPID identifier; ensures a leading letter.
 *
 * The character class is `\p{L}` / `\p{Nd}` rather than `[A-Za-z0-9]` because
 * that is what C#'s `char.IsLetterOrDigit` accepts, and a port that quietly
 * narrowed it would rename a program the Unity exporter leaves alone. (RAPID
 * itself wants ASCII identifiers, so a non-ASCII program name is a problem on
 * both sides — one worth reporting, not one worth diverging over.)
 */
function sanitizeIdent(raw: string): string {
  if (!raw) return 'rvProg';
  let s = '';
  for (const c of raw) s += /[\p{L}\p{Nd}_]/u.test(c) ? c : '_';
  if (!/^\p{L}/u.test(s)) s = `rv${s}`;
  return s;
}
